use std::env;
use axum::{Router, body::{Body, to_bytes}, extract::Request, http::{HeaderMap, StatusCode, header}, response::{IntoResponse, Response}, routing::{any, get, post}};
use fullstack_agent_045::{RequestInput, calculate};
use serde::Serialize;
use serde_json::json;
use tower_http::services::{ServeDir, ServeFile};

const MAX_BODY_BYTES: usize = 16_384;
const BROWSER_MODULE: &str = r#"const asI64=(v,n)=>{if(typeof v==='bigint')return v;if(!Number.isSafeInteger(v))throw new TypeError(`${n} must be a safe whole number`);return BigInt(v)};export async function loadParley(){const r=await fetch(new URL('/fullstack_agent_045.wasm',import.meta.url));const m=(await WebAssembly.instantiateStreaming(r)).instance.exports;return {microgrid_bid_score:(a0,a1,a2,a3,a4)=>m.parley_browser_score(asI64(a0,'a0'),asI64(a1,'a1'),asI64(a2,'a2'),asI64(a3,'a3'),a4?1:0)}}"#;

fn json_response(value: impl Serialize, status: u16, headers: &[(&str, &str)]) -> Response {
    if headers.iter().any(|(n, _)| matches!(n.to_ascii_lowercase().as_str(), "content-length" | "content-type" | "connection" | "transfer-encoding" | "x-content-type-options")) { return error("invalid_response_headers", 500, "server-owned response header"); }
    let mut response = (StatusCode::from_u16(status).unwrap(), serde_json::to_vec(&value).unwrap()).into_response();
    response.headers_mut().insert(header::CONTENT_TYPE, header::HeaderValue::from_static("application/json"));
    for (n, v) in headers { response.headers_mut().insert(header::HeaderName::from_bytes(n.as_bytes()).unwrap(), header::HeaderValue::from_str(v).unwrap()); }
    response
}
fn error(code: &str, status: u16, detail: &str) -> Response { let mut r = (StatusCode::from_u16(status).unwrap(), serde_json::to_vec(&json!({"error":code,"detail":detail})).unwrap()).into_response(); r.headers_mut().insert(header::CONTENT_TYPE, header::HeaderValue::from_static("application/json")); r }
fn zero(v: &RequestInput, state: &str) -> serde_json::Value { json!({"bid_key":v.bid_key,"generation_units":0,"battery_buffer_units":0,"grid_required_units":0,"grid_capacity_units":0,"delivered_units":0,"shortfall_units":0,"dispatch_windows":0,"bid_score":0,"bid_state":state}) }

fn decide(v: RequestInput, headers: &HeaderMap) -> Response {
    if headers.get("x-grid-key").and_then(|x| x.to_str().ok()).unwrap_or("") != "grid-045" { return json_response(zero(&v, "authorization_required"), 401, &[("www-authenticate", "GridKey")]); }
    if [v.solar_arrays, v.wind_turbines, v.storage_banks, v.interconnects].iter().any(|x| *x < 0) { return json_response(zero(&v, "invalid"), 422, &[("x-validation", "nonnegative")]); }
    if v.interconnects == 0 && v.solar_arrays * 9 + v.wind_turbines * 13 > 0 { return json_response(zero(&v, "invalid"), 422, &[("x-validation", "interconnects")]); }
    if v.duplicate_bid { return json_response(zero(&v, "duplicate"), 409, &[("x-conflict", "duplicate_bid")]); }
    let output = calculate(&v);
    let location = format!("/api/v9/microgrid-bids/{}", v.bid_key);
    let state = output.bid_state.clone();
    json_response(output, 202, &[("location", location.as_str()), ("retry-after", "3"), ("x-bid-state", state.as_str())])
}

async fn status() -> Response { json_response(json!({"service":"Microgrid Bid","ready":true}), 200, &[]) }
async fn endpoint(request: Request) -> Response {
    let headers = request.headers().clone();
    let media = headers.get(header::CONTENT_TYPE).and_then(|v| v.to_str().ok()).unwrap_or("").split(';').next().unwrap_or("").trim().to_ascii_lowercase();
    if media != "application/json" && !media.ends_with("+json") { return error("json_content_type_required", 415, "expected application/json"); }
    if let Some(length) = headers.get(header::CONTENT_LENGTH) { let declared = length.to_str().ok().and_then(|v| v.parse::<usize>().ok()); if declared.is_none_or(|v| v > MAX_BODY_BYTES) { return error("body_too_large", 413, "request body exceeds 16384 bytes"); } }
    let body = match to_bytes(request.into_body(), MAX_BODY_BYTES).await { Ok(body) => body, Err(_) => return error("body_too_large", 413, "request body exceeds 16384 bytes") };
    match serde_json::from_slice::<RequestInput>(&body) { Ok(v) => decide(v, &headers), Err(reason) => error("invalid_json", 400, &reason.to_string()) }
}
async fn missing(request: Request<Body>) -> Response { error("not_found", 404, &format!("no API route {}", request.uri().path())) }
async fn browser() -> Response { let mut r = BROWSER_MODULE.into_response(); r.headers_mut().insert(header::CONTENT_TYPE, header::HeaderValue::from_static("text/javascript; charset=utf-8")); r }
#[tokio::main]
async fn main() { let wasm = env::var_os("FULLSTACK_045_WASM").map(std::path::PathBuf::from).unwrap(); let app = Router::new().route("/status/microgrid-bid-ready", get(status)).route("/api/v9/microgrid-bids", post(endpoint)).route("/api/{*rest}", any(missing)).route("/parley.js", get(browser)).route_service("/fullstack_agent_045.wasm", ServeFile::new(wasm)).fallback_service(ServeDir::new("public").append_index_html_on_directories(true)); let port = env::var("PARLEY_WEB_PORT").unwrap().parse::<u16>().unwrap(); let listener = tokio::net::TcpListener::bind(("127.0.0.1", port)).await.unwrap(); axum::serve(listener, app).await.unwrap(); }
